/**
 * TradeDesk · Contract Application Portal - Backend
 * Google Apps Script
 */

const SPREADSHEET_ID = '';
const CONTRACTS_SHEET = 'Contracts';
const USERS_SHEET = 'Users';
const MIN_PRICE = 3000;

// URLs des plateformes de paiement
const PAYMENT_URLS = {
  kraken: 'https://www.kraken.com/',
  traderepublic: 'https://traderepublic.com/',
  coinbase: 'https://www.coinbase.com/',
  cryptocom: 'https://crypto.com/',
  bforbank: 'https://www.bforbank.com/'
};

function doGet(e) {
  return HtmlService.createHtmlOutputFromFile('Index')
    .setTitle('TradeDesk · Contract Portal')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

function getOrCreateSpreadsheet() {
  let ss;
  if (SPREADSHEET_ID) {
    try { ss = SpreadsheetApp.openById(SPREADSHEET_ID); }
    catch (e) { ss = SpreadsheetApp.create('TradeDesk Data'); }
  } else {
    const files = DriveApp.getFilesByName('TradeDesk Data');
    ss = files.hasNext() ? SpreadsheetApp.open(files.next()) : SpreadsheetApp.create('TradeDesk Data');
  }

  let contracts = ss.getSheetByName(CONTRACTS_SHEET);
  if (!contracts) {
    contracts = ss.insertSheet(CONTRACTS_SHEET);
    contracts.appendRow([
      'Timestamp', 'Client Name', 'Email', 'Market', 'Asset / Pair',
      'Contract Type', 'Direction', 'Contract Price (EUR)',
      'Leverage', 'Payment Method', 'Status', 'Contract ID'
    ]);
    contracts.getRange('1:1').setFontWeight('bold')
      .setBackground('#1e40af').setFontColor('#ffffff');
    contracts.setFrozenRows(1);
  }

  let users = ss.getSheetByName(USERS_SHEET);
  if (!users) {
    users = ss.insertSheet(USERS_SHEET);
    users.appendRow(['Timestamp', 'Full Name', 'Email', 'Phone', 'Password']);
    users.getRange('1:1').setFontWeight('bold')
      .setBackground('#1e40af').setFontColor('#ffffff');
    users.setFrozenRows(1);
  }
  return ss;
}

/* ================= AUTH ================= */

function registerUser(data) {
  try {
    const { fullName, email, phone, password } = data || {};
    if (!fullName || !email || !phone || !password) {
      return { success: false, error: 'All fields are required.' };
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return { success: false, error: 'Invalid email address.' };
    }
    if (String(phone).replace(/\D/g, '').length < 4) {
      return { success: false, error: 'Invalid phone number.' };
    }
    if (String(password).length < 4) {
      return { success: false, error: 'Password must be at least 4 characters.' };
    }

    const ss = getOrCreateSpreadsheet();
    const users = ss.getSheetByName(USERS_SHEET);
    const lastRow = users.getLastRow();
    if (lastRow > 1) {
      const emails = users.getRange(2, 3, lastRow - 1, 1).getValues().flat();
      if (emails.map(e => String(e).toLowerCase()).includes(email.toLowerCase())) {
        return { success: false, error: 'An account with this email already exists.' };
      }
    }
    users.appendRow([new Date(), fullName, email, String(phone), String(password)]);
    return { success: true, user: { fullName, email, phone: String(phone) } };
  } catch (err) {
    return { success: false, error: err.toString() };
  }
}

function loginUser(data) {
  try {
    const { email, password } = data || {};
    if (!email || !password) {
      return { success: false, error: 'Email and password are required.' };
    }
    const ss = getOrCreateSpreadsheet();
    const users = ss.getSheetByName(USERS_SHEET);
    const lastRow = users.getLastRow();
    if (lastRow <= 1) {
      return { success: false, error: 'No account found. Please register first.' };
    }
    const rows = users.getRange(2, 1, lastRow - 1, 5).getValues();
    for (const r of rows) {
      if (String(r[2]).toLowerCase() === email.toLowerCase() &&
          String(r[4]) === String(password)) {
        return { success: true, user: { fullName: r[1], email: r[2], phone: r[3] } };
      }
    }
    return { success: false, error: 'Incorrect email or password.' };
  } catch (err) {
    return { success: false, error: err.toString() };
  }
}

/* ================= CONTRACTS ================= */

function submitContractApplication(data) {
  try {
    const {
      clientName, email, market, asset, contractType,
      direction, price, leverage, paymentMethod
    } = data || {};
    if (!clientName || !email || !market || !asset || !price || !paymentMethod) {
      return { success: false, error: 'Missing required fields' };
    }
    const numericPrice = parseFloat(price);
    if (isNaN(numericPrice) || numericPrice < MIN_PRICE) {
      return { success: false, error: `Contract price must be at least €${MIN_PRICE.toLocaleString()}.` };
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return { success: false, error: 'Please enter a valid email address' };
    }

    const ss = getOrCreateSpreadsheet();
    const sheet = ss.getSheetByName(CONTRACTS_SHEET);
    const contractId = 'TC-' + Utilities.getUuid().replace(/-/g, '').substring(0, 8).toUpperCase();
    sheet.appendRow([
      new Date(), clientName, email, market, asset,
      contractType || 'Spot', direction || 'Long',
      numericPrice, leverage || '1x', paymentMethod,
      'Pending Review', contractId
    ]);

    return {
      success: true, contractId,
      message: 'Contract application submitted successfully',
      price: numericPrice,
      paymentMethod: paymentMethod,
      redirectUrl: PAYMENT_URLS[paymentMethod] || null,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return { success: false, error: error.toString() };
  }
}

function getMyContracts(email, limit) {
  try {
    limit = limit || 3;
    const ss = getOrCreateSpreadsheet();
    const sheet = ss.getSheetByName(CONTRACTS_SHEET);
    const lastRow = sheet.getLastRow();
    if (lastRow <= 1) return [];
    const data = sheet.getRange(2, 1, lastRow - 1, 12).getValues();
    return data
      .filter(r => String(r[2]).toLowerCase() === String(email).toLowerCase())
      .map(r => ({
        timestamp: r[0] instanceof Date ? r[0].toISOString() : String(r[0]),
        clientName: r[1], email: r[2], market: r[3], asset: r[4],
        contractType: r[5], direction: r[6], price: r[7],
        leverage: r[8], paymentMethod: r[9], status: r[10], contractId: r[11]
      }))
      .reverse()
      .slice(0, limit);
  } catch (err) {
    return [];
  }
}

